} from 'react-native';
import type { ImageResizeMode } from 'react-native';
import { Action, Chip, Label, Note, Panel } from '../components/Kit';
import { s, useTheme } from '../theme';

const landscape = require('../assets/landscape.png');

export function ImageDemo() {
