import React, { useEffect, useState } from 'react';
import {
  ActionSheetIOS,
  Alert,
  AppState,
  BackHandler,
  Dimensions,
  InputAccessoryView,
  Keyboard,
  KeyboardAvoidingView,
  Linking,
  PermissionsAndroid,
  PixelRatio,
  Platform,
  Share,
  StatusBar,
  ToastAndroid,
  Vibration,
  View,
  useColorScheme,
  useWindowDimensions,
} from 'react-native';
import Clipboard from '@react-native-clipboard/clipboard';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { WebView } from 'react-native-webview';
import { Action, Field, Label, Note, Panel } from '../components/Kit';
import { s, useTheme } from '../theme';


export function KeyboardDemo() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const show = Keyboard.addListener('keyboardDidShow', () =>
      setVisible(true),
    );
    const hide = Keyboard.addListener('keyboardDidHide', () =>
      setVisible(false),
    );
    return () => {
      show.remove();
      hide.remove();
    };
  }, []);
  return (
    <View style={s.demo}>
      <Field
        accessibilityLabel="Input mở bàn phím"
        placeholder="Chạm để mở bàn phím"
      />
      <Action title="Keyboard.dismiss()" onPress={Keyboard.dismiss} />
      <Note>keyboardDidShow/Hide: {visible ? 'Đang hiện' : 'Đang ẩn'}</Note>
    </View>
  );
}

