  Action,
  Chip,
  Label,
  Note,
  Panel,
  useDemoTimeout,
} from '../components/Kit';
import { useReduceMotion } from '../hooks/useReduceMotion';
import { s, useTheme } from '../theme';


export function SkeletonDemo() {
  const t = useTheme();
  const [loading, setLoading] = useState(true);
  const opacity = useRef(new Animated.Value(1)).current;
  const reduced = useReduceMotion();
  useEffect(() => {
    if (!loading || reduced) {
      opacity.setValue(1);
      return;
    }
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(opacity, {
          toValue: 0.35,
          duration: 650,
          useNativeDriver: true,
        }),
        Animated.timing(opacity, {
          toValue: 1,
          duration: 650,
          useNativeDriver: true,
        }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [loading, opacity, reduced]);
  return (
    <View style={s.demo}>
      {loading ? (
        <Animated.View style={[s.card, { opacity, borderColor: t.border }]}>
          <View
            style={{ height: 130, backgroundColor: t.border, borderRadius: 12 }}
          />
          <View
            style={{
              height: 20,
              width: '75%',
              backgroundColor: t.border,
              borderRadius: 6,
            }}
          />
          <View
            style={{
              height: 14,
              width: '50%',
              backgroundColor: t.border,
              borderRadius: 6,
            }}
          />
        </Animated.View>
      ) : (
        <Panel>
          <Label>✓ Nội dung đã tải</Label>
          <Label muted>Placeholder được thay bằng nội dung thật.</Label>
        </Panel>
      )}
      <Action
        title={loading ? 'Hiện dữ liệu' : 'Hiện skeleton'}
        onPress={() => setLoading(v => !v)}
      />
      <Label muted>Reduce Motion: {String(reduced)}</Label>
    </View>
  );
}

