import React, { useEffect, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Animated,
  Modal,
  Pressable,
  Switch,
  Text,
  View,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import {
  Action,
  Chip,
  Label,
  Note,
  Panel,
  useDemoTimeout,
} from '../components/Kit';
import { useReduceMotion } from '../hooks/useReduceMotion';
import { s, useTheme } from '../theme';


export function SnackbarDemo() {
  const t = useTheme();
  const [exists, setExists] = useState(true);
  const [visible, setVisible] = useState(false);
  const generation = useRef(0);
  const delay = useDemoTimeout();
  return (
    <View style={s.demo}>
      <Panel>
        <Label>
          {exists ? 'Một ghi chú có thể xóa.' : 'Ghi chú đã bị xóa.'}
        </Label>
        <Action
          disabled={!exists}
          title="Xóa ghi chú"
          onPress={() => {
            setExists(false);
            setVisible(true);
            const current = ++generation.current;
            delay(() => {
              if (generation.current === current) {
                setVisible(false);
              }
            }, 5000);
          }}
        />
      </Panel>
      {visible && (
        <View
          style={[
            s.between,
            { padding: 14, backgroundColor: t.soft, borderRadius: 14 },
          ]}
        >
          <Text
            accessibilityLiveRegion="polite"
            style={{ color: t.text, flex: 1 }}
          >
            Đã xóa ghi chú
          </Text>
          <Action
            secondary
            title="Hoàn tác"
            onPress={() => {
              generation.current++;
              setExists(true);
              setVisible(false);
            }}
          />
        </View>
      )}
      <Label muted>Thông báo tự đóng sau 5 giây.</Label>
    </View>
  );
}

