import React, { useMemo, useState } from 'react';
import {
  Keyboard,
  Platform,
  Pressable,
  Switch,
  Text,
  View,
} from 'react-native';
import Slider from '@react-native-community/slider';
import DateTimePicker from '@react-native-community/datetimepicker';
import { Picker } from '@react-native-picker/picker';
import {
  Action,
  Field,
  Label,
  Note,
  Panel,
  useDemoTimeout,
} from '../components/Kit';
import { normalizeSearch } from '../data/catalog';
import { s, useTheme } from '../theme';


export function FormDemo() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [status, setStatus] = useState('');
  const [loading, setLoading] = useState(false);
  const delay = useDemoTimeout();
  const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
  return (
    <View style={s.demo}>
      <Label>Email</Label>
      <Field
        accessibilityLabel="Email"
        placeholder="ban@example.com"
        inputMode="email"
        autoCapitalize="none"
        autoCorrect={false}
        value={email}
        onChangeText={value => {
          setEmail(value);
          setStatus('');
        }}
        onBlur={() => setTouched(true)}
        editable={!loading}
      />
      {touched && !valid && (
        <Label>⚠ Nhập email có dạng ten@example.com.</Label>
      )}
      <Action
        disabled={loading}
        title={loading ? 'Đang xử lý…' : 'Submit form'}
        onPress={() => {
          setTouched(true);
          Keyboard.dismiss();
          if (!valid) {
            return;
          }
          setLoading(true);
          delay(() => {
            setLoading(false);
            setStatus(
              '✓ Form hợp lệ. Đây là submit mô phỏng, không gửi dữ liệu.',
            );
          });
        }}
      />
      <Text accessibilityLiveRegion="polite">
        <Label>{status}</Label>
      </Text>
    </View>
  );
}

