import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Animated,
  Easing,
  LayoutAnimation,
  PanResponder,
  Text,
  View,
} from 'react-native';
import { Action, Chip, Label, Note } from '../components/Kit';
import { useReduceMotion } from '../hooks/useReduceMotion';
import { s, useTheme } from '../theme';


export function AnimatedDemo() {
  const t = useTheme();
  const value = useRef(new Animated.Value(0)).current;
  const target = useRef(false);
  const [mode, setMode] = useState('timing');
  const reduced = useReduceMotion();
  useEffect(() => () => value.stopAnimation(), [value]);
  const play = () => {
    target.current = !target.current;
    const toValue = target.current ? 1 : 0;
    if (reduced) {
      value.setValue(toValue);
      return;
    }
    value.stopAnimation();
    if (mode === 'spring') {
      Animated.spring(value, {
        toValue,
        friction: 5,
        tension: 70,
        useNativeDriver: true,
      }).start();
    } else {
      Animated.timing(value, {
        toValue,
        duration: 700,
        easing: Easing.inOut(Easing.ease),
        useNativeDriver: true,
      }).start();
    }
  };
  return (
    <View style={s.demo}>
      <View style={[s.center, { height: 200 }]}>
        <Animated.View
          style={[
            s.tile,
            {
              backgroundColor: t.primary,
              width: 90,
              height: 90,
              opacity: value.interpolate({
                inputRange: [0, 1],
                outputRange: [0.5, 1],
              }),
              transform: [
                {
                  translateX: value.interpolate({
                    inputRange: [0, 1],
                    outputRange: [-60, 60],
                  }),
                },
                {
                  scale: value.interpolate({
                    inputRange: [0, 1],
                    outputRange: [0.8, 1.2],
                  }),
                },
              ],
            },
          ]}
        >
          <Text style={{ color: t.onPrimary, fontWeight: '800' }}>RN</Text>
        </Animated.View>
      </View>
      <View style={s.row}>
        {['timing', 'spring'].map(x => (
          <Chip
            key={x}
            title={x}
            selected={mode === x}
            onPress={() => setMode(x)}
          />
        ))}
      </View>
      <Action title="Phát animation" onPress={play} />
      <Label muted>Reduce Motion: {String(reduced)}</Label>
    </View>
  );
}

